/* ---------- the PNG (made on the phone, offline; uploaded by the sketch job) ---------- */

/** The page's canvas factory (Node passes none, run_app 69 a stub). */
function appSketchCanvas(w, h) {
  var c = APP.doc.createElement('canvas');
  c.width = w;
  c.height = h;
  return c;
}
